/// `table`. The one node whose schema def is a two-branch `oneOf`, both under the same
/// `type: "table"`: an org-flavour table carries ROWS, a `table.el`-flavour one carries its raw
/// text as a single string, and neither ever carries both.
///
/// Modelling that as a `Flavour` enum is where typing pays here. In the untyped tree a consumer
/// has to know by folklore which key to look for, and reading `children` on a table.el table
/// silently yields nothing.
public struct OrgTable: Equatable, Sendable {
    public enum Flavour: Equatable, Sendable {
        case org(rows: [OrgTableRow])
        case tableEl(value: String)
    }

    public let flavour: Flavour
    public let tblfm: [String]?
    public let postBlank: Int
    public let affiliated: OrgAffiliated?

    public init(flavour: Flavour, tblfm: [String]?, postBlank: Int,
                affiliated: OrgAffiliated? = nil) {
        self.flavour = flavour
        self.tblfm = tblfm
        self.postBlank = postBlank
        self.affiliated = affiliated
    }

    public init(_ json: OrgJSON) throws {
        let o = try ASTDecode.object(json, "table")
        try ASTDecode.expectType(o, "table")
        self.tblfm = try ASTDecode.stringArrayOpt(o, "tblfm", in: "table")
        self.postBlank = try ASTDecode.int(o, "postBlank", in: "table")
        self.affiliated = try ASTDecode.affiliatedOpt(o, "affiliated", in: "table")
        // Dispatch on which branch is PRESENT. Neither, or both, is a malformed tree rather
        // than a defaultable case -- silently preferring one would invent a table.
        switch (o["children"], o["value"]) {
        case (.some, .some):
            throw ASTDecode.fail("table: carries both children and value; the schema's oneOf "
                                 + "permits exactly one")
        case (.some, .none):
            self.flavour = .org(rows: try ASTDecode.nestedList(
                OrgTableRow.self, o, "children", in: "table"))
        case (.none, .some):
            self.flavour = .tableEl(value: try ASTDecode.string(o, "value", in: "table"))
        case (.none, .none):
            throw ASTDecode.fail("table: has neither children nor value")
        }
    }

    public func toJSON() -> OrgJSON {
        var o: [String: OrgJSON] = ["type": .string("table")]
        o["tblfm"] = tblfm.map { OrgJSON.array($0.map { .string($0) }) } ?? .null
        o["postBlank"] = .int(postBlank)
        if let a = affiliated { o["affiliated"] = a.toJSON() }
        switch flavour {
        case .org(let rows): o["children"] = .array(rows.map { $0.toJSON() })
        case .tableEl(let value): o["value"] = .string(value)
        }
        return .object(o)
    }
}


// MARK: - OrgNode

/// Any node in the tree, tagged by its org-element type.
///
/// Exhaustive: a `switch` over this covers every type the oracle maps, and the compiler says so.
/// That is the property the untyped tree cannot offer -- a new node type added upstream is a
/// silently skipped branch there and a build error here.
public indirect enum OrgNode: Equatable, Sendable {
    case babelCall(OrgBabelCall)
    case bold(OrgBold)
    case centerBlock(OrgCenterBlock)
    case citation(OrgCitation)
    case citationReference(OrgCitationReference)
    case clock(OrgClock)
    case code(OrgCode)
    case comment(OrgComment)
    case commentBlock(OrgCommentBlock)
    case diarySexp(OrgDiarySexp)
    case document(OrgDocument)
    case drawer(OrgDrawer)
    case dynamicBlock(OrgDynamicBlock)
    case entity(OrgEntity)
    case exampleBlock(OrgExampleBlock)
    case exportBlock(OrgExportBlock)
    case exportSnippet(OrgExportSnippet)
    case fixedWidth(OrgFixedWidth)
    case footnoteDefinition(OrgFootnoteDefinition)
    case footnoteReference(OrgFootnoteReference)
    case headline(OrgHeadline)
    case horizontalRule(OrgHorizontalRule)
    case inlineBabelCall(OrgInlineBabelCall)
    case inlineSrcBlock(OrgInlineSrcBlock)
    case italic(OrgItalic)
    case item(OrgItem)
    case keyword(OrgKeyword)
    case latexEnvironment(OrgLatexEnvironment)
    case latexFragment(OrgLatexFragment)
    case lineBreak(OrgLineBreak)
    case link(OrgLink)
    case list(OrgList)
    case macro(OrgMacro)
    case nodeProperty(OrgNodeProperty)
    case paragraph(OrgParagraph)
    case planning(OrgPlanning)
    case propertyDrawer(OrgPropertyDrawer)
    case quoteBlock(OrgQuoteBlock)
    case radioTarget(OrgRadioTarget)
    case section(OrgSection)
    case specialBlock(OrgSpecialBlock)
    case srcBlock(OrgSrcBlock)
    case statisticsCookie(OrgStatisticsCookie)
    case strikethrough(OrgStrikethrough)
    case `subscript`(OrgSubscript)
    case superscript(OrgSuperscript)
    case table(OrgTable)
    case tableCell(OrgTableCell)
    case tableRow(OrgTableRow)
    case target(OrgTarget)
    case text(OrgText)
    case timestamp(OrgTimestamp)
    case underline(OrgUnderline)
    case verbatim(OrgVerbatim)
    case verseBlock(OrgVerseBlock)
}

extension OrgNode: ASTNode {
    /// The org-element type string this node carries in the JSON tree.
    public var typeName: String {
        switch self {
        case .babelCall: return "babel-call"
        case .bold: return "bold"
        case .centerBlock: return "center-block"
        case .citation: return "citation"
        case .citationReference: return "citation-reference"
        case .clock: return "clock"
        case .code: return "code"
        case .comment: return "comment"
        case .commentBlock: return "comment-block"
        case .diarySexp: return "diary-sexp"
        case .document: return "document"
        case .drawer: return "drawer"
        case .dynamicBlock: return "dynamic-block"
        case .entity: return "entity"
        case .exampleBlock: return "example-block"
        case .exportBlock: return "export-block"
        case .exportSnippet: return "export-snippet"
        case .fixedWidth: return "fixed-width"
        case .footnoteDefinition: return "footnote-definition"
        case .footnoteReference: return "footnote-reference"
        case .headline: return "headline"
        case .horizontalRule: return "horizontal-rule"
        case .inlineBabelCall: return "inline-babel-call"
        case .inlineSrcBlock: return "inline-src-block"
        case .italic: return "italic"
        case .item: return "item"
        case .keyword: return "keyword"
        case .latexEnvironment: return "latex-environment"
        case .latexFragment: return "latex-fragment"
        case .lineBreak: return "line-break"
        case .link: return "link"
        case .list: return "list"
        case .macro: return "macro"
        case .nodeProperty: return "node-property"
        case .paragraph: return "paragraph"
        case .planning: return "planning"
        case .propertyDrawer: return "property-drawer"
        case .quoteBlock: return "quote-block"
        case .radioTarget: return "radio-target"
        case .section: return "section"
        case .specialBlock: return "special-block"
        case .srcBlock: return "src-block"
        case .statisticsCookie: return "statistics-cookie"
        case .strikethrough: return "strikethrough"
        case .`subscript`: return "subscript"
        case .superscript: return "superscript"
        case .table: return "table"
        case .tableCell: return "table-cell"
        case .tableRow: return "table-row"
        case .target: return "target"
        case .text: return "text"
        case .timestamp: return "timestamp"
        case .underline: return "underline"
        case .verbatim: return "verbatim"
        case .verseBlock: return "verse-block"
        }
    }

    public init(_ json: OrgJSON) throws {
        let o = try ASTDecode.object(json, "node")
        guard let tag = o["type"]?.stringValue else {
            throw ASTDecode.fail("node: missing a type key: \(json)")
        }
        switch tag {
        case "babel-call": self = .babelCall(try OrgBabelCall(json))
        case "bold": self = .bold(try OrgBold(json))
        case "center-block": self = .centerBlock(try OrgCenterBlock(json))
        case "citation": self = .citation(try OrgCitation(json))
        case "citation-reference": self = .citationReference(try OrgCitationReference(json))
        case "clock": self = .clock(try OrgClock(json))
        case "code": self = .code(try OrgCode(json))
        case "comment": self = .comment(try OrgComment(json))
        case "comment-block": self = .commentBlock(try OrgCommentBlock(json))
        case "diary-sexp": self = .diarySexp(try OrgDiarySexp(json))
        case "document": self = .document(try OrgDocument(json))
        case "drawer": self = .drawer(try OrgDrawer(json))
        case "dynamic-block": self = .dynamicBlock(try OrgDynamicBlock(json))
        case "entity": self = .entity(try OrgEntity(json))
        case "example-block": self = .exampleBlock(try OrgExampleBlock(json))
        case "export-block": self = .exportBlock(try OrgExportBlock(json))
        case "export-snippet": self = .exportSnippet(try OrgExportSnippet(json))
        case "fixed-width": self = .fixedWidth(try OrgFixedWidth(json))
        case "footnote-definition": self = .footnoteDefinition(try OrgFootnoteDefinition(json))
        case "footnote-reference": self = .footnoteReference(try OrgFootnoteReference(json))
        case "headline": self = .headline(try OrgHeadline(json))
        case "horizontal-rule": self = .horizontalRule(try OrgHorizontalRule(json))
        case "inline-babel-call": self = .inlineBabelCall(try OrgInlineBabelCall(json))
        case "inline-src-block": self = .inlineSrcBlock(try OrgInlineSrcBlock(json))
        case "italic": self = .italic(try OrgItalic(json))
        case "item": self = .item(try OrgItem(json))
        case "keyword": self = .keyword(try OrgKeyword(json))
        case "latex-environment": self = .latexEnvironment(try OrgLatexEnvironment(json))
        case "latex-fragment": self = .latexFragment(try OrgLatexFragment(json))
        case "line-break": self = .lineBreak(try OrgLineBreak(json))
        case "link": self = .link(try OrgLink(json))
        case "list": self = .list(try OrgList(json))
        case "macro": self = .macro(try OrgMacro(json))
        case "node-property": self = .nodeProperty(try OrgNodeProperty(json))
        case "paragraph": self = .paragraph(try OrgParagraph(json))
        case "planning": self = .planning(try OrgPlanning(json))
        case "property-drawer": self = .propertyDrawer(try OrgPropertyDrawer(json))
        case "quote-block": self = .quoteBlock(try OrgQuoteBlock(json))
        case "radio-target": self = .radioTarget(try OrgRadioTarget(json))
        case "section": self = .section(try OrgSection(json))
        case "special-block": self = .specialBlock(try OrgSpecialBlock(json))
        case "src-block": self = .srcBlock(try OrgSrcBlock(json))
        case "statistics-cookie": self = .statisticsCookie(try OrgStatisticsCookie(json))
        case "strikethrough": self = .strikethrough(try OrgStrikethrough(json))
        case "subscript": self = .`subscript`(try OrgSubscript(json))
        case "superscript": self = .superscript(try OrgSuperscript(json))
        case "table": self = .table(try OrgTable(json))
        case "table-cell": self = .tableCell(try OrgTableCell(json))
        case "table-row": self = .tableRow(try OrgTableRow(json))
        case "target": self = .target(try OrgTarget(json))
        case "text": self = .text(try OrgText(json))
        case "timestamp": self = .timestamp(try OrgTimestamp(json))
        case "underline": self = .underline(try OrgUnderline(json))
        case "verbatim": self = .verbatim(try OrgVerbatim(json))
        case "verse-block": self = .verseBlock(try OrgVerseBlock(json))
        default:
            throw ASTDecode.fail("node: unknown org-element type \"\(tag)\". The typed layer is generated from schema/org-node.schema.json; regenerate it if the schema gained a type.")
        }
    }

    public func toJSON() -> OrgJSON {
        switch self {
        case .babelCall(let x): return x.toJSON()
        case .bold(let x): return x.toJSON()
        case .centerBlock(let x): return x.toJSON()
